import { connection } from 'next/server'

export default async function Page() {
  await connection()
  const now = new Date()
  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>
        Rendered at: <time dateTime={now.toISOString()}>{now.toISOString()}</time>
      </p>
      <p>Reload the page — the timestamp changes on every request.</p>
    </main>
  )
}
